  const listed = spawnSync("git", ["config", "--show-scope", "-z", "--get-regexp", GIT_PROGRAM_KEYS], { cwd: workspacePath, encoding: "utf8", timeout: 10_000 });
  if (listed.status === 1 && !listed.stdout) return false;
  if (listed.status !== 0) return true;
